# ---------------------------------------------------------------------------
# Background utility tasks
# ---------------------------------------------------------------------------


@celery_app.task(
    name="tasks.process_campaign_website_leads",
    bind=True,
    max_retries=0,
    soft_time_limit=3600,
    time_limit=3900,
)
def process_campaign_website_leads(
    self,
    campaign_id: str,
    options: Optional[Dict[str, Any]] = None,
    request_base_url: Optional[str] = None,
) -> Dict[str, Any]:
    """Run the selected has-website repair/audit/outreach workflow in Celery."""
    safe_options = options or {}
    logger.info(
        "[Website Lead Process] Task %s started for campaign %s: lead_count=%d force_audit=%s regenerate_outreach=%s update_gmail=%s manual_verification=%s.",
        getattr(getattr(self, "request", None), "id", None),
        campaign_id,
        len(safe_options.get("lead_ids") or []),
        safe_options.get("force_audit"),
        safe_options.get("regenerate_outreach"),
        safe_options.get("update_gmail_draft"),
        safe_options.get("manual_verification"),
    )
    try:
        from app.routes.audits import _process_campaign_website_leads_job

        result = asyncio.run(
            _process_campaign_website_leads_job(
                campaign_id=campaign_id,
                options=safe_options,
                request_base_url=request_base_url,
            )
        )
        logger.info(
            "[Website Lead Process] Task %s completed for campaign %s: processed=%s failed=%s.",
            getattr(getattr(self, "request", None), "id", None),
            campaign_id,
            result.get("processed"),
            result.get("failed"),
        )
        return result
    except Exception as exc:
        logger.error(
            "[Website Lead Process] Task %s failed for campaign %s: %s",
            getattr(getattr(self, "request", None), "id", None),
            campaign_id,
            exc,
            exc_info=True,
        )
        return {"status": "failed", "campaign_id": campaign_id, "error": str(exc)}


@celery_app.task(
    name="tasks.audit_campaign_websites",
    bind=True,
    max_retries=0,
    soft_time_limit=3600,
    time_limit=3900,
)
def audit_campaign_websites(
    self,
    campaign_id: str,
    lead_ids: Optional[List[str]] = None,
    manual_verification: bool = False,
    force: bool = False,
    request_base_url: Optional[str] = None,
) -> Dict[str, Any]:
    """Audit campaign websites in Celery; backs POST /campaigns/{id}/audit-websites."""
    from types import SimpleNamespace

    from app.routes.audits import _audit_leads, _campaign_leads

    task_id = getattr(getattr(self, "request", None), "id", None)
    logger.info(
        "[Website Audit] Task %s started for campaign %s.",
        task_id,
        campaign_id,
    )
    try:
        selected = {str(lid).strip() for lid in (lead_ids or []) if str(lid).strip()}
        leads = _campaign_leads(campaign_id, selected_ids=selected)
        request = SimpleNamespace(base_url=request_base_url or get_settings().base_url)
        result = asyncio.run(
            _audit_leads(
                campaign_id=campaign_id,
                request=request,
                leads=leads,
                manual_verification=manual_verification,
                force=force,
                blocked_only=False,
            )
        )
        logger.info(
            "[Website Audit] Task %s completed for campaign %s.",
            task_id,
            campaign_id,
        )
        return result.model_dump(mode="json")
    except Exception as exc:
        logger.error(
            "[Website Audit] Task %s failed for campaign %s: %s",
            task_id,
            campaign_id,
            exc,
            exc_info=True,
        )
        return {"status": "failed", "campaign_id": campaign_id, "error": str(exc)}


@celery_app.task(
    name="tasks.repair_campaign_websites",
    bind=True,
    max_retries=0,
    soft_time_limit=3600,
    time_limit=3900,
)
def repair_campaign_websites(
    self,
    campaign_id: str,
    reset_status: bool = True,
) -> Dict[str, Any]:
    logger.info("[Website Repair] Starting Maps website repair for campaign %s.", campaign_id)
    campaign = get_document(CAMPAIGNS, campaign_id)
    if not campaign:
        return {"status": "failed", "reason": "campaign_not_found", "campaign_id": campaign_id}

    update_document(
        CAMPAIGNS,
        campaign_id,
        {
            "progress": {
                "stage": "repairing_websites",
                "message": "Rechecking Google Maps detail rows for missing websites.",
            }
        },
    )

    leads = query_collection(
        LEADS,
        filters=[
            ("campaign_id", "==", campaign_id),
            ("has_website", "==", False),
        ],
        limit=5000,
    )
    leads_by_id = {lead["id"]: lead for lead in leads}
    repair_candidates = [
        {
            "lead_id": lead["id"],
            "business_name": lead.get("business_name") or "",
            "google_maps_url": lead.get("google_maps_url") or "",
            "repair_fields": ["details"],
        }
        for lead in leads
        if lead.get("google_maps_url")
    ]

    result = {
        "status": "completed",
        "campaign_id": campaign_id,
        "checked": 0,
        "repaired": 0,
        "failed": 0,
        "no_website_found": 0,
        "missing_google_maps_url": sum(1 for lead in leads if not lead.get("google_maps_url")),
        "notion_synced": 0,
        "notion_skipped": 0,
    }
    if not repair_candidates:
        update_document(
            CAMPAIGNS,
            campaign_id,
            {
                "status": "scraped",
                "stats.website_repair": result,
                "progress": {
                    "stage": "website_repair_complete",
                    "message": "No missing-website leads had Google Maps URLs to recheck.",
                },
            },
        )
        return result

    try:
        repaired = asyncio.run(_repair_maps_listing_details(repair_candidates, campaign_id=campaign_id))
    except asyncio.CancelledError:
        update_document(
            CAMPAIGNS,
            campaign_id,
            {
                "status": "cancelled",
                "progress": {
                    "stage": "cancelled",
                    "message": "Website repair cancelled.",
                },
            },
        )
        return {"status": "cancelled", "campaign_id": campaign_id, **result}

    notion = get_notion_sync()
    campaign_notion_page_id = campaign.get("notion_page_id")
    for item in repaired:
        result["checked"] += 1
        lead_id = item.get("lead_id")
        business_name = item.get("business_name") or ""
        logger.info(
            "[Website Repair] Applying result for lead %s (%s): status=%s",
            lead_id,
            business_name,
            item.get("repair_status"),
        )
        if item.get("repair_status") == "failed":
            result["failed"] += 1
            if lead_id:
                update_document(LEADS, lead_id, {
                    "website_repair_status": "failed",
                    "website_repair_error": item.get("repair_error"),
                })
            logger.info("[Website Repair] Lead %s marked failed.", lead_id)
            continue

        website = (item.get("website") or "").strip()
        if not website:
            result["no_website_found"] += 1
            if lead_id:
                update_document(LEADS, lead_id, {"website_repair_status": "checked_no_website_found"})
            logger.info("[Website Repair] Lead %s checked: no website found.", lead_id)
            continue

        if not website.startswith(("http://", "https://")):
            website = "https://" + website
        if not _looks_like_valid_website(website):
            result["no_website_found"] += 1
            if lead_id:
                update_document(LEADS, lead_id, {"website_repair_status": "checked_no_official_website_found"})
            logger.info("[Website Repair] Lead %s checked: website candidate was non-official and was discarded.", lead_id)
            continue
        update_payload: Dict[str, Any] = {
            "website": website,
            "has_website": True,
            "missing_website": False,
            "website_repair_status": "repaired",
            "website_repaired_at": firestore.SERVER_TIMESTAMP,
            "google_maps_url": item.get("google_maps_url"),
            "website_domain": _get_domain(website),
        }
        repaired_address = (item.get("address") or "").strip()
        existing_address = (leads_by_id.get(lead_id, {}).get("address") or "").strip()
        if _looks_like_domain(repaired_address):
            update_payload["address"] = None
        elif repaired_address:
            update_payload["address"] = repaired_address
        elif _looks_like_domain(existing_address):
            update_payload["address"] = None
        if reset_status:
            update_payload["scrape_status"] = "pending"
        update_document(LEADS, lead_id, update_payload)
        result["repaired"] += 1
        logger.info(
            "[Website Repair] Lead %s repaired: website=%s address=%s reset_status=%s",
            lead_id,
            website,
            update_payload.get("address", "(unchanged)"),
            reset_status,
        )

        lead = get_document(LEADS, lead_id) or {}
        notion_page_id = notion.sync_lead(
            lead_id,
            lead,
            campaign_notion_page_id=campaign_notion_page_id,
        )
        if notion_page_id:
            update_document(LEADS, lead_id, {"notion_page_id": notion_page_id})
            result["notion_synced"] += 1
            logger.info("[Website Repair] Lead %s synced to Notion page %s.", lead_id, notion_page_id)
        elif notion.enabled:
            result["notion_skipped"] += 1
            logger.warning("[Website Repair] Lead %s was repaired but Notion sync returned no page id.", lead_id)

    update_document(
        CAMPAIGNS,
        campaign_id,
        {
            "status": "scraped",
            "stats.website_repair": result,
            "progress": {
                "stage": "website_repair_complete",
                "message": (
                    f"Website repair complete: {result['repaired']} leads repaired, "
                    f"{result['no_website_found']} still missing websites."
                ),
            },
        },
    )
    logger.info("[Website Repair] Completed for campaign %s: %s", campaign_id, result)
    return result


@celery_app.task(
    name="tasks.repair_campaign_maps_data",
    bind=True,
    max_retries=0,
    soft_time_limit=7200,
    time_limit=7500,
)
def repair_campaign_maps_data(
    self,
    campaign_id: str,
    fields: Any = "auto",
    force: bool = False,
    lead_ids: Optional[List[str]] = None,
    sync_notion: bool = True,
) -> Dict[str, Any]:
    """Refresh Maps-derived fields for all existing leads in a campaign."""
    logger.info(
        "[Maps Data Repair] Starting Google Maps data repair for campaign %s (fields=%s, force=%s, lead_ids=%s, sync_notion=%s).",
        campaign_id,
        fields,
        force,
        len(lead_ids or []),
        sync_notion,
    )
    campaign = get_document(CAMPAIGNS, campaign_id)
    if not campaign:
        return {"status": "failed", "reason": "campaign_not_found", "campaign_id": campaign_id}

    update_document(
        CAMPAIGNS,
        campaign_id,
        {
            "progress": {
                "stage": "repairing_maps_data",
                "message": "Refreshing saved leads from their Google Maps listing URLs.",
            }
        },
    )

    plan = build_maps_repair_plan(campaign_id, fields=fields, force=force, lead_ids=lead_ids)
    leads_by_id = {
        lead["id"]: lead
        for lead in query_collection(LEADS, filters=[("campaign_id", "==", campaign_id)], limit=5000)
    }
    repair_candidates = plan["candidates"]
    detail_repair_candidates: List[Dict[str, Any]] = []
    media_repair_candidates: List[Dict[str, Any]] = []
    for candidate in repair_candidates:
        candidate_fields = set(candidate.get("repair_fields") or [])
        non_media_fields = [field for field in candidate.get("repair_fields") or [] if field != "media"]
        if non_media_fields:
            detail_repair_candidates.append({**candidate, "repair_fields": non_media_fields})
        if "media" in candidate_fields:
            media_repair_candidates.append(candidate)
    for candidate in repair_candidates:
        logger.info(
            "[Maps Data Repair] Lead %s needs Maps repair fields: %s",
            candidate.get("lead_id"),
            ",".join(candidate.get("repair_fields") or []),
        )
    for skipped in plan["skipped"]:
        logger.info(
            "[Maps Data Repair] Lead %s skipped: requested Maps data is valid.",
            skipped.get("lead_id"),
        )
    result = {
        "status": "completed",
        "campaign_id": campaign_id,
        "fields": plan["fields"],
        "force": force,
        "selected_leads": plan["total_selected"],
        "checked": 0,
        "updated": 0,
        "failed": 0,
        "missing_google_maps_url": plan["missing_google_maps_url"],
        "websites_updated": 0,
        "addresses_updated": 0,
        "phones_updated": 0,
        "ratings_updated": 0,
        "reviews_updated": 0,
        "review_avatars_uploaded": 0,
        "skipped_valid": plan["skipped_valid"],
        "details_repaired": 0,
        "ratings_repaired": 0,
        "reviews_repaired": 0,
        "media_repaired": 0,
        "media_failed": 0,
        "media_uploaded_images": 0,
        "media_uploaded_videos": 0,
        "notion_synced": 0,
        "notion_skipped": 0,
    }
    if not repair_candidates:
        message = (
            "All campaign leads with Google Maps URLs already have valid Maps data."
            if plan["skipped_valid"]
            else "No campaign leads had Google Maps URLs to refresh."
        )
        update_document(
            CAMPAIGNS,
            campaign_id,
            {
                "status": "scraped",
                "stats.maps_data_repair": result,
                "progress": {
                    "stage": "maps_data_repair_complete",
                    "message": message,
                },
            },
        )
        return result

    try:
        repaired = (
            asyncio.run(_repair_maps_listing_details(detail_repair_candidates, campaign_id=campaign_id))
            if detail_repair_candidates
            else []
        )
    except asyncio.CancelledError:
        update_document(
            CAMPAIGNS,
            campaign_id,
            {
                "status": "cancelled",
                "progress": {
                    "stage": "cancelled",
                    "message": "Google Maps data repair cancelled.",
                },
            },
        )
        return {"status": "cancelled", **result}

    notion = get_notion_sync()
    campaign_notion_page_id = campaign.get("notion_page_id")
    cloudinary_available = False
    upload_review_avatars = None
    scrape_upload_listing_media = None
    try:
        from app.services.maps_media_scraper import (
            cloudinary_configured,
            scrape_upload_listing_media as scrape_media,
            upload_review_avatars as upload_avatars,
        )

        cloudinary_available = cloudinary_configured()
        upload_review_avatars = upload_avatars
        scrape_upload_listing_media = scrape_media
    except Exception as exc:
        logger.info("[Maps Data Repair] Reviewer avatar upload unavailable: %s", exc)

    for item in repaired:
        result["checked"] += 1
        lead_id = item.get("lead_id")
        business_name = item.get("business_name") or ""
        logger.info(
            "[Maps Data Repair] Applying result for lead %s (%s): status=%s",
            lead_id,
            business_name,
            item.get("repair_status"),
        )
        if item.get("repair_status") == "failed":
            result["failed"] += 1
            if lead_id:
                update_document(LEADS, lead_id, {
                    "maps_data_repair_status": "failed",
                    "maps_data_repair_error": item.get("repair_error"),
                    "maps_data_repaired_at": firestore.SERVER_TIMESTAMP,
                })
            logger.info("[Maps Data Repair] Lead %s marked failed: %s", lead_id, item.get("repair_error"))
            continue
        if item.get("repair_status") == "missing_google_maps_url":
            logger.info("[Maps Data Repair] Lead %s skipped: missing Google Maps URL.", lead_id)
            continue
        if not lead_id:
            result["failed"] += 1
            logger.info("[Maps Data Repair] Skipping result without lead id: %s", item)
            continue

        normalized, _validation_metrics = _normalize_raw_lead_fields(item)
        existing = leads_by_id.get(lead_id, {})
        repair_fields = set(item.get("repair_fields") or ["details", "rating", "reviews"])
        wants_website = bool(repair_fields.intersection({"details", "website"}))
        wants_address = bool(repair_fields.intersection({"details", "address"}))
        wants_phone = bool(repair_fields.intersection({"details", "phone"}))
        update_payload: Dict[str, Any] = {
            "google_maps_url": item.get("google_maps_url"),
            "maps_data_repair_status": "repaired",
            "maps_data_repair_error": None,
            "maps_data_repaired_at": firestore.SERVER_TIMESTAMP,
            "maps_data_repair_checked_fields": sorted(repair_fields),
            "updated_at": firestore.SERVER_TIMESTAMP,
        }

        if wants_website and normalized.get("website"):
            update_payload.update({
                "website": normalized.get("website"),
                "has_website": True,
                "missing_website": False,
                "website_domain": normalized.get("website_domain"),
            })
            if normalized.get("website") != existing.get("website"):
                result["websites_updated"] += 1
        elif wants_website and existing.get("website") and not _looks_like_valid_website(existing.get("website")):
            update_payload.update({
                "website": None,
                "has_website": False,
                "missing_website": True,
                "website_domain": "",
            })
            result["websites_updated"] += 1
            logger.info("[Maps Data Repair] Lead %s existing website was non-official and was cleared.", lead_id)

        if wants_address and "address" in normalized:
            update_payload["address"] = normalized.get("address")
            if normalized.get("address") != existing.get("address"):
                result["addresses_updated"] += 1

        phone = (normalized.get("phone") or "").strip()
        if wants_phone and phone:
            update_payload["phone"] = phone
            update_payload["phone_key"] = re.sub(r"\D+", "", phone)
            if phone != existing.get("phone"):
                result["phones_updated"] += 1

        if wants_website or wants_address or wants_phone:
            result["details_repaired"] += 1

        if "rating" in repair_fields and item.get("google_rating") is not None:
            update_payload["google_rating"] = item.get("google_rating")
            if item.get("google_rating") != existing.get("google_rating"):
                result["ratings_updated"] += 1
        if ("rating" in repair_fields or "reviews" in repair_fields) and item.get("google_review_count") is not None:
            update_payload["google_review_count"] = item.get("google_review_count")
        if "rating" in repair_fields and item.get("google_review_count") is not None:
            result["ratings_repaired"] += 1
        if "reviews" in repair_fields:
            update_payload["google_reviews_url"] = firestore.DELETE_FIELD

        reviews = _carry_existing_review_avatars(
            (item.get("google_reviews") or [])[:9],
            existing.get("google_reviews") or [],
        )
        if "reviews" in repair_fields and reviews:
            if cloudinary_available and upload_review_avatars:
                before_uploaded = sum(1 for review in reviews if review.get("avatar_cloudinary_public_id"))
                try:
                    reviews = upload_review_avatars(
                        lead_id=lead_id,
                        business_name=business_name,
                        reviews=reviews,
                        campaign_id=campaign_id,
                    )
                    after_uploaded = sum(1 for review in reviews if review.get("avatar_cloudinary_public_id"))
                    result["review_avatars_uploaded"] += max(0, after_uploaded - before_uploaded)
                except Exception as exc:
                    logger.warning(
                        "[Maps Data Repair] Lead %s reviewer avatar upload failed: %s",
                        lead_id,
                        exc,
                    )
            reviews = _sanitize_google_reviews(reviews)
            update_payload["google_reviews"] = reviews
            if reviews != _sanitize_google_reviews(existing.get("google_reviews") or []):
                result["reviews_updated"] += 1
            result["reviews_repaired"] += 1
        elif "reviews" in repair_fields and existing.get("google_reviews"):
            update_payload["google_reviews"] = []
            result["reviews_updated"] += 1
            result["reviews_repaired"] += 1

        update_document(LEADS, lead_id, update_payload)
        result["updated"] += 1
        logger.info(
            "[Maps Data Repair] Lead %s updated: website=%s address=%s phone=%s rating=%s reviews=%s",
            lead_id,
            update_payload.get("website", existing.get("website") or "unchanged"),
            update_payload.get("address"),
            update_payload.get("phone", existing.get("phone") or "unchanged"),
            update_payload.get("google_rating", existing.get("google_rating") or "unchanged"),
            len(update_payload.get("google_reviews") or []),
        )

        lead = get_document(LEADS, lead_id) or {}
        if sync_notion:
            notion_page_id = notion.sync_lead(
                lead_id,
                lead,
                campaign_notion_page_id=campaign_notion_page_id,
            )
            if notion_page_id:
                update_document(LEADS, lead_id, {"notion_page_id": notion_page_id})
                result["notion_synced"] += 1
                logger.info("[Maps Data Repair] Lead %s synced to Notion page %s.", lead_id, notion_page_id)
            elif notion.enabled:
                result["notion_skipped"] += 1
                logger.warning("[Maps Data Repair] Lead %s was repaired but Notion sync returned no page id.", lead_id)

    settings = get_settings()
    max_images = max(0, min(settings.maps_listing_media_max_images, 12))
    max_videos = max(0, min(settings.maps_listing_media_max_videos, 1))
    for candidate in media_repair_candidates:
        lead_id = candidate.get("lead_id")
        if not lead_id:
            result["media_failed"] += 1
            continue
        existing = get_document(LEADS, lead_id) or leads_by_id.get(lead_id, {})
        business_name = existing.get("business_name") or candidate.get("business_name") or "unknown business"
        if _looks_like_valid_listing_images(existing.get("google_listing_images"), target_count=max_images):
            logger.info(
                "[Maps Data Repair] Lead %s media skipped: existing listing images are complete.",
                lead_id,
            )
            continue
        if not cloudinary_available or not scrape_upload_listing_media:
            result["media_failed"] += 1
            logger.warning(
                "[Maps Data Repair] Lead %s media repair skipped: Cloudinary/media scraper unavailable.",
                lead_id,
            )
            update_document(LEADS, lead_id, {
                "google_listing_media_status": "failed",
                "google_listing_media_error": "Cloudinary/media scraper unavailable",
                "google_listing_media_updated_at": firestore.SERVER_TIMESTAMP,
            })
            continue
        try:
            logger.info(
                "[Maps Data Repair] Lead %s (%s): repairing listing media because saved images are missing or incomplete.",
                lead_id,
                business_name,
            )
            media_result = asyncio.run(scrape_upload_listing_media(
                lead_id=lead_id,
                business_name=business_name,
                google_maps_url=candidate.get("google_maps_url") or existing.get("google_maps_url") or "",
                max_images=max_images,
                max_videos=max_videos,
                campaign_id=campaign_id,
            ))
            checked_fields = sorted(set(existing.get("maps_data_repair_checked_fields") or []) | {"media"})
            update_document(LEADS, lead_id, {
                "google_listing_images": media_result.images,
                "google_listing_videos": media_result.videos,
                "google_listing_source_image_urls": media_result.source_image_urls,
                "google_listing_source_video_urls": media_result.source_video_urls,
                "google_listing_media_status": media_result.status,
                "google_listing_media_error": media_result.error,
                "google_listing_media_updated_at": firestore.SERVER_TIMESTAMP,
                "maps_data_repair_checked_fields": checked_fields,
                "maps_data_repaired_at": firestore.SERVER_TIMESTAMP,
                "updated_at": firestore.SERVER_TIMESTAMP,
            })
            result["updated"] += 1
            result["media_repaired"] += 1
            result["media_uploaded_images"] += len(media_result.images)
            result["media_uploaded_videos"] += len(media_result.videos)
            logger.info(
                "[Maps Data Repair] Lead %s media repaired: status=%s images=%d videos=%d.",
                lead_id,
                media_result.status,
                len(media_result.images),
                len(media_result.videos),
            )
        except Exception as exc:
            result["media_failed"] += 1
            logger.error(
                "[Maps Data Repair] Lead %s media repair failed: %s",
                lead_id,
                exc,
                exc_info=True,
            )
            update_document(LEADS, lead_id, {
                "google_listing_media_status": "failed",
                "google_listing_media_error": str(exc),
                "google_listing_media_updated_at": firestore.SERVER_TIMESTAMP,
                "maps_data_repaired_at": firestore.SERVER_TIMESTAMP,
                "updated_at": firestore.SERVER_TIMESTAMP,
            })

    update_document(
        CAMPAIGNS,
        campaign_id,
        {
            "status": "scraped",
            "stats.maps_data_repair": result,
            "progress": {
                "stage": "maps_data_repair_complete",
                "message": (
                    f"Google Maps data repair complete: {result['updated']} leads updated, "
                    f"{result['failed']} failed."
                ),
            },
        },
    )
    logger.info("[Maps Data Repair] Completed for campaign %s: %s", campaign_id, result)
    return result


@celery_app.task(
    name="tasks.build_campaign_static_websites",
    bind=True,
    max_retries=0,
    soft_time_limit=1800,
    time_limit=2100,
)
def build_campaign_static_websites(
    self,
    campaign_id: str,
    lead_ids: Optional[List[str]] = None,
    pull_from_notion: bool = True,
    sync_to_notion: bool = True,
    preview_base_url: Optional[str] = None,
    batch_size: int = 25,
) -> Dict[str, Any]:
    """Generate static websites for leads marked needs_website=true."""
    logger.info(
        "[Websites] Starting static website generation for campaign %s.",
        campaign_id,
        extra={
            "event": "static_websites_build_started",
            "campaign_id": campaign_id,
            "lead_ids": lead_ids,
            "pull_from_notion": pull_from_notion,
            "sync_to_notion": sync_to_notion,
            "preview_base_url": preview_base_url,
            "batch_size": batch_size,
        },
    )
    campaign = get_document(CAMPAIGNS, campaign_id)
    if not campaign:
        return {"status": "failed", "reason": "campaign_not_found", "campaign_id": campaign_id}

    update_document(
        CAMPAIGNS,
        campaign_id,
        {
            "progress": {
                "stage": "building_static_websites",
                "message": "Pulling Notion lead edits and generating static websites.",
            }
        },
    )

    selected_ids = set(lead_ids or [])
    notion = get_notion_sync()
    pulled_from_notion = 0
    if pull_from_notion and notion.enabled:
        try:
            from app.routes.scrape import _pull_leads_from_notion
            pull_candidates = _website_generation_candidates(campaign_id, selected_ids)
            pulled_from_notion = _pull_leads_from_notion(campaign_id, pull_candidates, notion)
            logger.info(
                "[Websites] Pulled %d lead updates from Notion before generation.",
                pulled_from_notion,
            )
        except Exception:
            logger.exception("[Websites] Failed to pull Notion lead updates before generation.")

    leads = _website_generation_candidates(campaign_id, selected_ids)

    from app.services.static_website_generator import (
        build_static_website_for_lead,
        eligible_for_static_website,
        generated_website_to_dict,
        remove_generated_website_path,
        websites_root,
    )

    result: Dict[str, Any] = {
        "status": "completed",
        "campaign_id": campaign_id,
        "websites_root": str(websites_root()),
        "checked": len(leads),
        "generated": 0,
        "skipped": 0,
        "failed": 0,
        "pulled_from_notion": pulled_from_notion,
        "notion_synced": 0,
        "notion_skipped": 0,
        "items": [],
    }

    existing_slugs: set[str] = set()
    lead_batches = _chunked(leads, batch_size)
    result["batch_size"] = max(1, int(batch_size or 1))
    result["batches"] = len(lead_batches)
    for batch_index, lead_batch in enumerate(lead_batches, start=1):
        logger.info(
            "[Websites] Processing build batch %d/%d for campaign %s (%d leads).",
            batch_index,
            len(lead_batches),
            campaign_id,
            len(lead_batch),
        )
        update_document(
            CAMPAIGNS,
            campaign_id,
            {
                "progress": {
                    "stage": "building_static_websites",
                    "message": f"Building website preview batch {batch_index}/{len(lead_batches)}.",
                }
            },
        )
        for lead in lead_batch:
            lead_id = lead["id"]
            try:
                if not eligible_for_static_website(lead):
                    reason = "needs_website_not_checked"
                    result["skipped"] += 1
                    result["items"].append({
                        "lead_id": lead_id,
                        "business_name": lead.get("business_name"),
                        "skipped": True,
                        "reason": reason,
                    })
                    logger.info("[Websites] Lead %s skipped: %s.", lead_id, reason)
                    continue
                if lead.get("generated_website_slug"):
                    logger.info("[Websites] Lead %s already has a preview; rebuilding preview files.", lead_id)
                    previous_path = lead.get("generated_website_path") or str(websites_root() / str(lead.get("generated_website_slug")))
                    if lead.get("generated_website_status") != "hosted":
                        removed = remove_generated_website_path(previous_path)
                        if removed:
                            logger.info(
                                "[Websites] Removed previous preview for lead %s at %s.",
                                lead_id,
                                previous_path,
                            )
                        else:
                            logger.warning(
                                "[Websites] Could not remove previous preview for lead %s at %s.",
                                lead_id,
                                previous_path,
                            )

                generated = build_static_website_for_lead(
                    lead,
                    campaign,
                    existing_slugs=existing_slugs,
                    overwrite=True,
                )
                item = generated_website_to_dict(generated)
                item["url"] = None
                item["preview_url"] = _local_preview_url(generated.slug, preview_base_url)
                result["items"].append(item)
                if generated.skipped:
                    result["skipped"] += 1
                    logger.info("[Websites] Lead %s skipped: %s.", lead_id, generated.reason)
                    continue

                update_document(
                    LEADS,
                    lead_id,
                    {
                        "generated_website_slug": generated.slug,
                        "generated_website_path": generated.path,
                        "generated_website_url": None,
                        "generated_website_status": "preview",
                        "generated_website_files": generated.files,
                    },
                )
                if sync_to_notion:
                    updated_lead = get_document(LEADS, lead_id) or {**lead, "id": lead_id}
                    campaign_notion_page_id = campaign.get("notion_page_id")
                    notion_page_id = notion.sync_lead(
                        lead_id,
                        updated_lead,
                        campaign_notion_page_id=campaign_notion_page_id,
                    )
                    if notion_page_id:
                        update_document(LEADS, lead_id, {"notion_page_id": notion_page_id})
                        result["notion_synced"] += 1
                        logger.info("[Websites] Lead %s synced to Notion page %s.", lead_id, notion_page_id)
                    elif notion.enabled:
                        result["notion_skipped"] += 1
                        logger.warning("[Websites] Lead %s generated but Notion sync was skipped.", lead_id)
                result["generated"] += 1
                logger.info(
                    "[Websites] Lead %s generated at %s.",
                    lead_id,
                    generated.path,
                    extra={
                        "event": "static_website_generated",
                        "campaign_id": campaign_id,
                        "lead_id": lead_id,
                        "slug": generated.slug,
                        "url": generated.url,
                    },
                )
            except Exception as exc:
                result["failed"] += 1
                result["items"].append({
                    "lead_id": lead_id,
                    "business_name": lead.get("business_name"),
                    "skipped": False,
                    "reason": "generation_failed",
                    "error": str(exc),
                })
                logger.error("[Websites] Lead %s generation failed: %s", lead_id, exc, exc_info=True)
        logger.info(
            "[Websites] Finished build batch %d/%d for campaign %s.",
            batch_index,
            len(lead_batches),
            campaign_id,
        )

    update_document(
        CAMPAIGNS,
        campaign_id,
        {
            "stats.generated_websites": {
                "checked": result["checked"],
                "generated": result["generated"],
                "skipped": result["skipped"],
                "failed": result["failed"],
                "pulled_from_notion": result["pulled_from_notion"],
                "notion_synced": result["notion_synced"],
                "notion_skipped": result["notion_skipped"],
            },
            "progress": {
                "stage": "static_websites_complete",
                "message": (
                    f"Generated {result['generated']} static websites; "
                    f"{result['skipped']} skipped, {result['failed']} failed."
                ),
            },
        },
    )
    logger.info("[Websites] Completed for campaign %s: %s", campaign_id, result)
    return result


def _website_generation_candidates(
    campaign_id: str,
    selected_ids: set[str],
) -> List[Dict[str, Any]]:
    if selected_ids:
        leads = []
        for lead_id in selected_ids:
            lead = get_document(LEADS, lead_id)
            if lead and lead.get("campaign_id") == campaign_id:
                leads.append(lead)
        return leads

    docs: List[Dict[str, Any]] = []
    offset = 0
    while True:
        page = query_collection(
            LEADS,
            filters=[("campaign_id", "==", campaign_id)],
            limit=500,
            offset=offset,
        )
        docs.extend(page)
        if len(page) < 500:
            return docs
        offset += 500


def _local_preview_url(slug: str, preview_base_url: Optional[str]) -> str:
    base = (preview_base_url or "http://127.0.0.1:8000").rstrip("/")
    return f"{base}/preview/{slug}/"


@celery_app.task(
    name="tasks.publish_campaign_static_websites",
    bind=True,
    max_retries=0,
    soft_time_limit=1800,
    time_limit=2100,
)
def publish_campaign_static_websites(
    self,
    campaign_id: str,
    lead_ids: Optional[List[str]] = None,
    commit_message: Optional[str] = None,
    pull_from_notion: bool = True,
    sync_to_notion: bool = True,
    batch_size: int = 25,
) -> Dict[str, Any]:
    """Generate missing opted-in websites, push them, and create outreach drafts."""
    logger.info(
        "[Websites Publish] Starting publish for campaign %s.",
        campaign_id,
        extra={
            "event": "static_websites_publish_started",
            "campaign_id": campaign_id,
            "lead_ids": lead_ids,
            "pull_from_notion": pull_from_notion,
            "sync_to_notion": sync_to_notion,
            "batch_size": batch_size,
        },
    )
    campaign = get_document(CAMPAIGNS, campaign_id)
    if not campaign:
        return {"status": "failed", "reason": "campaign_not_found", "campaign_id": campaign_id}

    settings = get_settings()
    if not settings.base_url:
        reason = "BASE_URL is not configured."
        logger.error("[Websites Publish] %s", reason)
        return {"status": "failed", "campaign_id": campaign_id, "reason": reason}

    update_document(
        CAMPAIGNS,
        campaign_id,
        {
            "progress": {
                "stage": "publishing_static_websites",
                "message": "Generating and publishing opted-in static websites.",
            }
        },
    )

    selected_ids = set(lead_ids or [])
    notion = get_notion_sync()
    pulled_from_notion = 0
    if pull_from_notion and notion.enabled:
        try:
            from app.routes.scrape import _pull_leads_from_notion
            pull_candidates = _website_generation_candidates(campaign_id, selected_ids)
            pulled_from_notion = _pull_leads_from_notion(campaign_id, pull_candidates, notion)
            logger.info(
                "[Websites Publish] Pulled %d lead updates from Notion before publishing.",
                pulled_from_notion,
            )
        except Exception:
            logger.exception("[Websites Publish] Failed to pull Notion lead updates before publishing.")

    candidates = _website_generation_candidates(campaign_id, selected_ids)
    result: Dict[str, Any] = {
        "status": "completed",
        "campaign_id": campaign_id,
        "checked": len(candidates),
        "pulled_from_notion": pulled_from_notion,
        "generated": 0,
        "published": 0,
        "failed": 0,
        "skipped": 0,
        "notion_synced": 0,
        "notion_skipped": 0,
        "items": [],
        "git": None,
        "batch_size": max(1, int(batch_size or 1)),
    }

    from app.services.static_website_generator import (
        build_static_website_for_lead,
        eligible_for_static_website,
        generated_website_to_dict,
        git_commit_and_push_websites,
        public_url_for_slug,
        remove_generated_website_path,
        websites_root,
    )

    generated_objects = []
    publishable_leads: List[Dict[str, Any]] = []
    existing_slugs: set[str] = set()
    total_candidates = len(candidates)
    logger.info(
        "[Websites Publish] Campaign %s evaluating %d website candidate(s).",
        campaign_id,
        total_candidates,
    )
    for index, lead in enumerate(candidates, start=1):
        lead_id = lead["id"]
        logger.info(
            "[Websites Publish] Evaluating lead %d/%d: %s (%s).",
            index,
            total_candidates,
            lead_id,
            lead.get("business_name"),
        )
        if lead.get("generated_website_url"):
            result["skipped"] += 1
            result["items"].append({
                "lead_id": lead_id,
                "business_name": lead.get("business_name"),
                "status": "skipped",
                "reason": "already_published",
                "url": lead.get("generated_website_url"),
            })
            logger.info("[Websites Publish] Lead %s skipped: already has generated website URL.", lead_id)
            continue
        if not eligible_for_static_website(lead):
            result["skipped"] += 1
            result["items"].append({
                "lead_id": lead_id,
                "business_name": lead.get("business_name"),
                "status": "skipped",
                "reason": "needs_website_not_checked",
            })
            logger.info("[Websites Publish] Lead %s skipped: needs_website is not checked.", lead_id)
            continue
        if not lead.get("emails"):
            result["skipped"] += 1
            result["items"].append({
                "lead_id": lead_id,
                "business_name": lead.get("business_name"),
                "status": "skipped",
                "reason": "missing_email",
            })
            logger.info("[Websites Publish] Lead %s skipped: no email available for outreach.", lead_id)
            continue

        try:
            previous_path = lead.get("generated_website_path") or (
                str(websites_root() / str(lead.get("generated_website_slug")))
                if lead.get("generated_website_slug")
                else None
            )
            if previous_path:
                removed = remove_generated_website_path(previous_path)
                if removed:
                    logger.info("[Websites Publish] Removed previous unhosted files for lead %s.", lead_id)
                else:
                    logger.warning("[Websites Publish] Could not remove previous files for lead %s at %s.", lead_id, previous_path)

            generated = build_static_website_for_lead(
                lead,
                campaign,
                existing_slugs=existing_slugs,
                overwrite=True,
            )
            item = generated_website_to_dict(generated)
            item["status"] = "generated"
            result["items"].append(item)
            if generated.skipped:
                result["skipped"] += 1
                logger.info("[Websites Publish] Lead %s skipped during generation: %s.", lead_id, generated.reason)
                continue

            update_payload = {
                "generated_website_slug": generated.slug,
                "generated_website_path": generated.path,
                "generated_website_url": None,
                "generated_website_status": "generated",
                "generated_website_files": generated.files,
            }
            update_document(LEADS, lead_id, update_payload)
            updated_lead = get_document(LEADS, lead_id) or {**lead, **update_payload}
            generated_objects.append(generated)
            publishable_leads.append(updated_lead)
            result["generated"] += 1
            logger.info("[Websites Publish] Lead %s generated at %s.", lead_id, generated.path)
        except Exception as exc:
            result["failed"] += 1
            result["items"].append({
                "lead_id": lead_id,
                "business_name": lead.get("business_name"),
                "status": "failed",
                "reason": "generation_failed",
                "error": str(exc),
            })
            logger.error("[Websites Publish] Lead %s generation failed: %s", lead_id, exc, exc_info=True)

    if not generated_objects:
        reason = "No opted-in websites were generated for publishing."
        logger.warning("[Websites Publish] %s", reason)
        result["status"] = "failed" if result["failed"] else "completed"
        result["reason"] = reason
        return result

    logger.info(
        "[Websites Publish] Campaign %s generated %d website(s); starting git publish.",
        campaign_id,
        len(generated_objects),
    )
    git_result = git_commit_and_push_websites(
        generated_objects,
        commit_message=commit_message,
        push=True,
    )
    result["git"] = git_result
    if git_result.get("error") or not git_result.get("pushed"):
        reason = git_result.get("error") or "Git push did not complete."
        logger.error("[Websites Publish] Publish failed for campaign %s: %s", campaign_id, reason)
        result["status"] = "failed"
        result["reason"] = reason
        update_document(
            CAMPAIGNS,
            campaign_id,
            {
                "progress": {
                    "stage": "static_websites_publish_failed",
                    "message": f"Website publish failed: {reason}",
                }
            },
        )
        return result

    logger.info(
        "[Websites Publish] Campaign %s git publish succeeded; updating %d lead(s).",
        campaign_id,
        len(publishable_leads),
    )
    hosted_at = datetime.now(timezone.utc).isoformat()
    lead_batches = _chunked(publishable_leads, batch_size)
    result["batches"] = len(lead_batches)
    for batch_index, lead_batch in enumerate(lead_batches, start=1):
        logger.info(
            "[Websites Publish] Processing publish batch %d/%d for campaign %s (%d leads).",
            batch_index,
            len(lead_batches),
            campaign_id,
            len(lead_batch),
        )
        update_document(
            CAMPAIGNS,
            campaign_id,
            {
                "progress": {
                    "stage": "publishing_static_websites",
                    "message": f"Marking published website batch {batch_index}/{len(lead_batches)}.",
                }
            },
        )
        for lead_index, lead in enumerate(lead_batch, start=1):
            lead_id = lead["id"]
            logger.info(
                "[Websites Publish] Marking lead %d/%d in batch %d/%d as hosted: %s (%s).",
                lead_index,
                len(lead_batch),
                batch_index,
                len(lead_batches),
                lead_id,
                lead.get("business_name"),
            )
            slug = lead.get("generated_website_slug") or ""
            live_url = public_url_for_slug(slug)
            if not live_url:
                result["failed"] += 1
                result["items"].append({
                    "lead_id": lead_id,
                    "business_name": lead.get("business_name"),
                    "status": "failed",
                    "reason": "live_url_not_available",
                })
                logger.error("[Websites Publish] Lead %s has no live URL after push.", lead_id)
                continue

            update_document(
                LEADS,
                lead_id,
                {
                    "generated_website_status": "hosted",
                    "generated_website_url": live_url,
                    "generated_website_hosted_at": hosted_at,
                },
            )
            updated_lead = get_document(LEADS, lead_id) or {**lead, "id": lead_id}
            if sync_to_notion:
                notion_page_id = notion.sync_lead(
                    lead_id,
                    updated_lead,
                    campaign_notion_page_id=campaign.get("notion_page_id"),
                )
                if notion_page_id:
                    update_document(LEADS, lead_id, {"notion_page_id": notion_page_id})
                    result["notion_synced"] += 1
                elif notion.enabled:
                    result["notion_skipped"] += 1

            result["published"] += 1
            result["items"].append({
                "lead_id": lead_id,
                "business_name": lead.get("business_name"),
                "slug": slug,
                "url": live_url,
                "status": "hosted",
            })
            logger.info(
                "[Websites Publish] Lead %s hosted at %s.",
                lead_id,
                live_url,
                extra={
                    "event": "static_website_hosted",
                    "campaign_id": campaign_id,
                    "lead_id": lead_id,
                    "slug": slug,
                    "url": live_url,
                },
            )

    update_document(
        CAMPAIGNS,
        campaign_id,
        {
            "stats.generated_websites.published": result["published"],
            "stats.generated_websites.publish_failed": result["failed"],
            "stats.generated_websites.publish_notion_synced": result["notion_synced"],
            "progress": {
                "stage": "static_websites_publish_complete",
                "message": (
                    f"Published {result['published']} generated websites; "
                    f"{result['failed']} failed."
                ),
            },
        },
    )
    outreach_result = _generate_campaign_outreach_drafts(campaign_id, [lead["id"] for lead in leads], batch_size)
    result["outreach"] = outreach_result
    update_document(
        CAMPAIGNS,
        campaign_id,
        {
            "stats.generated_websites.outreach_generated": outreach_result.get("generated", 0),
            "stats.generated_websites.outreach_skipped": outreach_result.get("skipped", 0),
            "stats.generated_websites.outreach_failed": outreach_result.get("failed", 0),
        },
    )
    logger.info("[Websites Publish] Completed for campaign %s: %s", campaign_id, result)
    return result


def _ensure_no_website_report_for_lead(
    lead: Dict[str, Any],
    campaign: Dict[str, Any],
) -> tuple[Optional[str], Optional[Dict[str, Any]], str]:
    lead_id = lead["id"]
    existing = query_collection(
        NO_WEBSITE_REPORTS,
        filters=[("lead_id", "==", lead_id)],
        limit=1,
    )
    if existing:
        return existing[0].get("id"), existing[0], "existing"

    campaign_id = campaign.get("id") or lead.get("campaign_id")
    niche = campaign.get("niche") or ""
    location = campaign.get("location") or ""
    business_name = lead.get("business_name") or ""
    logger.info("[Outreach] Lead %s has no no-website report; creating one before draft.", lead_id)
    from app.services.no_website_appraisal import appraise_no_website

    search_evidence = _get_campaign_search_evidence(campaign_id, niche, location)
    analysis = appraise_no_website(
        business_name=business_name,
        niche=niche,
        location=location,
        search_evidence=search_evidence,
    )
    analysis["search_evidence"] = search_evidence
    slug = _generate_slug(business_name, location, suffix="no-web")
    report_data = {
        "lead_id": lead_id,
        "slug": slug,
        "search_evidence": search_evidence,
        **analysis,
    }
    report_id = add_document(NO_WEBSITE_REPORTS, report_data)
    report_notion_page_id = get_notion_sync().sync_report(
        report_id,
        "no_website",
        report_data,
        lead_notion_page_id=lead.get("notion_page_id"),
    )
    if report_notion_page_id:
        update_document(NO_WEBSITE_REPORTS, report_id, {"notion_page_id": report_notion_page_id})
        report_data["notion_page_id"] = report_notion_page_id
    report_data["id"] = report_id
    logger.info("[Outreach] Lead %s no-website report created: %s.", lead_id, report_id)
    return report_id, report_data, "created"


def _generate_campaign_outreach_drafts(
    campaign_id: str,
    lead_ids: Optional[List[str]] = None,
    batch_size: int = 25,
) -> Dict[str, Any]:
    """Create Gmail drafts for published generated websites only."""
    logger.info(
        "[Outreach] Starting generated-site draft creation for campaign %s (lead_ids=%s).",
        campaign_id,
        lead_ids,
    )
    campaign = get_document(CAMPAIGNS, campaign_id)
    if not campaign:
        return {"status": "failed", "reason": "campaign_not_found", "campaign_id": campaign_id}

    settings = get_settings()
    selected_leads = _website_generation_candidates(campaign_id, set(lead_ids or []))
    result: Dict[str, Any] = {
        "status": "completed",
        "campaign_id": campaign_id,
        "checked": len(selected_leads),
        "generated": 0,
        "skipped": 0,
        "failed": 0,
        "batch_size": max(1, int(batch_size or 1)),
        "items": [],
    }

    lead_batches = _chunked(selected_leads, batch_size)
    result["batches"] = len(lead_batches)
    for batch_index, lead_batch in enumerate(lead_batches, start=1):
        logger.info(
            "[Outreach] Processing generated-site draft batch %d/%d for campaign %s (%d leads).",
            batch_index,
            len(lead_batches),
            campaign_id,
            len(lead_batch),
        )
        update_document(
            CAMPAIGNS,
            campaign_id,
            {
                "progress": {
                    "stage": "outreach_drafts_running",
                    "message": f"Creating outreach draft batch {batch_index}/{len(lead_batches)}.",
                }
            },
        )
        for lead in lead_batch:
            lead_id = lead["id"]
            lead_emails = lead.get("emails") or []
            live_url = (lead.get("generated_website_url") or "").strip()
            if lead.get("generated_website_status") != "hosted" or not live_url:
                reason = "missing_live_url"
                result["skipped"] += 1
                result["items"].append({
                    "lead_id": lead_id,
                    "business_name": lead.get("business_name"),
                    "skipped": True,
                    "reason": reason,
                })
                logger.info("[Outreach] Lead %s skipped: %s.", lead_id, reason)
                continue
            if not lead_emails:
                reason = "missing_email"
                result["skipped"] += 1
                result["items"].append({
                    "lead_id": lead_id,
                    "business_name": lead.get("business_name"),
                    "skipped": True,
                    "reason": reason,
                })
                logger.info("[Outreach] Lead %s skipped: %s.", lead_id, reason)
                continue

            report_id, report, report_source = _ensure_no_website_report_for_lead(lead, campaign)
            if not report_id or not report:
                reason = "missing_no_website_report"
                result["skipped"] += 1
                result["items"].append({
                    "lead_id": lead_id,
                    "business_name": lead.get("business_name"),
                    "skipped": True,
                    "reason": reason,
                })
                logger.info("[Outreach] Lead %s skipped: %s.", lead_id, reason)
                continue
            existing_drafts = query_collection(
                EMAIL_DRAFTS,
                filters=[
                    ("lead_id", "==", lead_id),
                    ("report_id", "==", report_id),
                ],
                limit=1,
            )
            if existing_drafts:
                result["skipped"] += 1
                result["items"].append({
                    "lead_id": lead_id,
                    "business_name": lead.get("business_name"),
                    "skipped": True,
                    "reason": "draft_already_exists",
                })
                logger.info("[Outreach] Lead %s skipped: draft already exists.", lead_id)
                continue

            try:
                _create_no_website_email_draft(
                    lead_id=lead_id,
                    report_id=report_id,
                    slug=report.get("slug") or _generate_slug(lead.get("business_name") or "", campaign.get("location") or "", suffix="no-web"),
                    business_name=lead.get("business_name") or "",
                    location=campaign.get("location") or "",
                    niche=campaign.get("niche") or "",
                    analysis=report,
                    emails=lead_emails,
                    campaign_id=campaign_id,
                    settings=settings,
                    lead_notion_page_id=lead.get("notion_page_id"),
                    report_notion_page_id=report.get("notion_page_id"),
                    generated_website_url=live_url,
                )
                result["generated"] += 1
                result["items"].append({
                    "lead_id": lead_id,
                    "business_name": lead.get("business_name"),
                    "skipped": False,
                    "reason": "draft_created",
                    "report_source": report_source,
                })
                logger.info("[Outreach] Lead %s outreach draft created.", lead_id)
            except Exception as exc:
                result["failed"] += 1
                result["items"].append({
                    "lead_id": lead_id,
                    "business_name": lead.get("business_name"),
                    "skipped": False,
                    "reason": "draft_failed",
                    "error": str(exc),
                })
                logger.error("[Outreach] Lead %s draft creation failed: %s", lead_id, exc, exc_info=True)

    update_document(
        CAMPAIGNS,
        campaign_id,
        {
            "progress": {
                "stage": "outreach_drafts_complete",
                "message": (
                    f"Generated {result['generated']} outreach drafts; "
                    f"{result['skipped']} skipped, {result['failed']} failed."
                ),
            }
        },
    )
    logger.info("[Outreach] Completed for campaign %s: %s", campaign_id, result)
    return result


def _parse_datetime(value: Any) -> Optional[datetime]:
    if not value:
        return None
    if isinstance(value, datetime):
        return value if value.tzinfo else value.replace(tzinfo=timezone.utc)
    try:
        text = str(value).replace("Z", "+00:00")
        parsed = datetime.fromisoformat(text)
        return parsed if parsed.tzinfo else parsed.replace(tzinfo=timezone.utc)
    except Exception:
        return None


def _query_all_collection(collection: str, filters: Optional[List[tuple]] = None) -> List[Dict[str, Any]]:
    docs: List[Dict[str, Any]] = []
    offset = 0
    while True:
        page = query_collection(collection, filters=filters, limit=500, offset=offset)
        docs.extend(page)
        if len(page) < 500:
            return docs
        offset += 500

def _next_follow_up_interval_days(settings: Any, current_follow_up_count: int) -> int:
    next_follow_up_number = int(current_follow_up_count or 0) + 1
    if next_follow_up_number >= 2:
        return int(
            getattr(settings, "outreach_follow_up_2_interval_days", 0)
            or settings.outreach_follow_up_interval_days
            or 3
        )
    return int(settings.outreach_follow_up_interval_days or 3)



def _due_follow_up_candidates(
    campaign_id: Optional[str],
    lead_ids: Optional[List[str]],
    limit: int,
) -> List[Dict[str, Any]]:
    settings = get_settings()
    max_follow_ups = int(settings.outreach_max_follow_ups or 0)
    selected_ids = set(lead_ids or [])
    filters = [("status", "==", "sent")]
    if campaign_id:
        filters.append(("campaign_id", "==", campaign_id))
    drafts = _query_all_collection(EMAIL_DRAFTS, filters=filters)
    now = datetime.now(timezone.utc)
    due: List[Dict[str, Any]] = []
    for draft in drafts:
        if selected_ids and draft.get("lead_id") not in selected_ids:
            continue
        if draft.get("parent_outreach_id"):
            continue
        if draft.get("reply_status") not in (None, "", "no_reply"):
            continue
        count = int(draft.get("follow_up_count") or 0)
        if count >= max_follow_ups:
            continue
        due_at = _parse_datetime(draft.get("follow_up_due_at"))
        if not due_at or due_at > now:
            continue
        due.append(draft)
        if len(due) >= limit:
            break
    return due


def _follow_up_stage(next_count: int) -> str:
    return f"follow_up_{next_count}"


def _is_follow_up_outreach(draft: Dict[str, Any]) -> bool:
    stage = str(draft.get("stage") or "").strip().lower()
    if stage.startswith("follow_up_"):
        return True
    return int(draft.get("follow_up_count") or 0) > 0


def _follow_up_subject(original: Dict[str, Any], lead: Dict[str, Any], next_count: int) -> str:
    workflow_type = original.get("workflow_type") or (
        "no_website" if original.get("report_type") == "no_website" else "has_website"
    )
    if workflow_type == "no_website":
        business_name = lead.get("business_name") or "your business"
        if next_count == 1:
            return f"Following up: website preview for {business_name}"
        return "Following up: closing the loop on the website preview"
    if next_count == 1:
        original_subject = str(original.get("subject") or "").strip() or "your website audit"
        return original_subject if original_subject.lower().startswith("re:") else f"Re: {original_subject}"
    return "Following up: closing the loop on your website audit"

def _primary_follow_up_finding(report: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    findings = (report or {}).get("findings") or []
    if not isinstance(findings, list):
        return {}
    preferred_categories = {
        "readability",
        "page speed",
        "page load",
        "layout stability",
        "mobile layout",
        "mobile usability",
        "conversion path",
        "trust",
        "message clarity",
        "copy clarity",
        "search basics",
        "visual trust",
    }
    for finding in findings:
        if isinstance(finding, dict) and str(finding.get("category") or "").strip().lower() in preferred_categories:
            return finding
    return {}


def _has_website_follow_up_issue_copy(finding: Dict[str, Any]) -> tuple[str, str]:
    category = str(finding.get("category") or "").strip().lower()
    observation = str(finding.get("email_observation") or finding.get("observation") or "one issue on the website").strip()

    if category == "readability":
        return (
            "One thing that stood out is that some important text on your mobile site doesn't stand out clearly from the background. Since many people compare several businesses before deciding who to contact, issues like this can make it harder for visitors to understand what you offer or how to contact you.",
            "The report goes into more detail, but the main takeaway is that addressing this could make your website easier for potential customers to use.",
        )
    if category in {"page speed", "page load"}:
        return (
            f"One thing that stood out is that {observation.rstrip('.')}. Since many people searching for cleaning services are comparing options quickly from their phones, that delay can mean they leave before seeing your services or how to contact you.",
            "The report goes into more detail, but the main takeaway is that improving the first load could help more visitors stay long enough to request a quote or call.",
        )
    if category == "layout stability":
        return (
            "One thing that stood out is that some content shifts around while the mobile page is loading. For a business like yours, that matters because someone may be trying to tap a call, quote, or booking button right as the page moves. That small interruption can make the site feel harder to use and can stop a ready visitor from taking the next step.",
            "The report goes into more detail, but the main takeaway is that keeping the page steady could help more visitors complete the action they already intended to take.",
        )
    if category == "mobile layout":
        return (
            "One thing that stood out is that some content extends beyond the width of the screen on mobile. When potential customers are comparing cleaning businesses on their phones, a site that feels awkward to navigate can be enough reason to leave and contact a competitor instead.",
            "The report goes into more detail, but the main takeaway is that this issue may be causing some potential customers to choose another business before they ever reach out to you.",
        )
    if category == "mobile usability":
        return (
            "One thing that stood out is that some buttons and clickable areas on mobile are small or tightly spaced. For someone trying to call, book, or request service from a phone, that can make it easier to tap the wrong thing, miss the action, or give up before reaching out.",
            "The report goes into more detail, but the main takeaway is that making those actions easier to tap could help more ready-to-contact visitors turn into actual calls or inquiries.",
        )
    if category == "conversion path":
        return (
            "One thing that stood out is that the next step for visitors is not obvious right away on mobile. If someone is ready to ask for pricing or schedule a cleaning, they should not have to search around to figure out what to click while they are comparing other providers.",
            "The report goes into more detail, but the main takeaway is that making the quote or contact path clearer could help more interested visitors become actual inquiries instead of leaving the page undecided.",
        )
    if category == "trust":
        return (
            "One thing that stood out is that the page could show stronger trust signals for first-time visitors. When someone is choosing a service provider they have not used before, proof like reviews, local credibility, service photos, and clear contact details can be the difference between reaching out and choosing a competitor.",
            "The report goes into more detail, but the main takeaway is that adding stronger proof could help more visitors feel comfortable trusting you with the job.",
        )
    if category == "message clarity":
        return (
            "One thing that stood out is that the main message could be clearer for first-time visitors. If the page does not quickly explain what you help with, who you serve, and why someone should choose you, visitors may compare mostly on price or move on to a site that makes the decision feel easier.",
            "The report goes into more detail, but the main takeaway is that clearer positioning could help potential customers understand the value of working with you before they start comparing only on cost.",
        )
    if category == "copy clarity":
        return (
            "One thing that stood out is that the page does not give enough persuasive context before asking visitors to take action. People comparing providers usually want to know what makes the service reliable, what kind of work is handled, and why they should trust the business before they call or request a quote.",
            "The report goes into more detail, but the main takeaway is that stronger copy could give visitors more reasons to contact you instead of moving on to another option.",
        )
    if category == "search basics":
        return (
            "One thing that stood out is that some basic search signals could be clearer, like the page title, description, or main heading. Those details help both Google and visitors quickly understand what service you offer and whether your business matches what they searched for.",
            "The report goes into more detail, but the main takeaway is that tightening those basics could make your site feel more relevant when people find it through search.",
        )
    if category == "visual trust":
        return (
            "One thing that stood out is that one or more images appear broken or missing. For a service business, visuals can quietly affect trust because visitors use the page to decide whether the business looks active, professional, and safe to contact.",
            "The report goes into more detail, but the main takeaway is that fixing missing visuals could help the website feel more maintained and credible before a potential customer decides who to contact.",
        )
    return (
        f"One thing that stood out is that {observation.rstrip('.')}. Since many people compare several businesses before deciding who to contact, issues like this can make it harder for visitors to understand your business or take the next step.",
        "The report goes into more detail, but the main takeaway is that addressing this could make your website easier for potential customers to use.",
    )

def _follow_up_body(original: Dict[str, Any], lead: Dict[str, Any], report: Optional[Dict[str, Any]], next_count: int) -> str:
    business_name = lead.get("business_name") or "there"
    workflow_type = original.get("workflow_type") or (
        "no_website" if original.get("report_type") == "no_website" else "has_website"
    )
    settings = get_settings()
    email_platform = str(original.get("email_platform") or "").strip()
    platform_note = f"Original email platform: {email_platform}." if email_platform else ""
    if workflow_type == "no_website":
        preview_url = original.get("generated_website_url") or lead.get("generated_website_url") or ""
        if next_count == 1:
            parts = [
                f"Hi {business_name} team,",
                f"A few days ago I put together a quick preview of what a website for {business_name} could look like: {preview_url}" if preview_url else f"A few days ago I put together a quick preview of what a website for {business_name} could look like.",
            ]
            if platform_note:
                parts.append(platform_note)
            parts.extend([
                "No pressure on this, it's just a starting point. If it's helpful, I can swap in your actual services and photos so you can see what it'd really look like, no cost to look at it.",
                "Would you like me to personalize it with your services and photos?",
                "Best regards,",
                "Andrew Ezeani",
                "Teerdox Technologies",
                "https://www.teerdox.com",
            ])
            return "\n\n".join(parts)
        parts = [
            f"Hi {business_name} team,",
            f"I'll leave this with you. A little while back I put together a preview of what a website for {business_name} could look like ({preview_url}). If that becomes something you want to explore later, it's still there." if preview_url else f"I'll leave this with you. A little while back I put together a preview of what a website for {business_name} could look like. If that becomes something you want to explore later, it's still there.",
        ]
        if platform_note:
            parts.append(platform_note)
        parts.extend([
            "Happy to help whenever the timing's right.",
            "All the best,",
            "Andrew Ezeani",
            "Teerdox Technologies",
            "https://www.teerdox.com",
        ])
        return "\n\n".join(parts)

    slug = (report or {}).get("slug") or ""
    report_base_url = settings.base_url.rstrip("/")
    report_url = f"{report_base_url}/audit/{slug}" if slug else ""
    if next_count == 1:
        issue_line, takeaway_line = _has_website_follow_up_issue_copy(_primary_follow_up_finding(report))
        parts = [
            f"Hi {business_name} team,",
            f"I wanted to follow up on the short website audit I sent over: {report_url}" if report_url else "I wanted to follow up on the short website audit I sent over.",
            issue_line,
            takeaway_line,
        ]
        if platform_note:
            parts.append(platform_note)
        parts.extend([
            "If this is something you'd like to address, would you like my help with the highest-impact fix?",
            "Best regards,\nAndrew Ezeani\nTeerdox Technologies\nhttps://www.teerdox.com",
        ])
        return "\n\n".join(parts)
    parts = [
        f"Hi {business_name} team,",
        "I don't want to keep cluttering your inbox, so I'll leave this here.",
        f"A little while back I put together a short audit of your website ({report_url}) with the two issues I'd prioritize fixing. If that becomes useful down the line, feel free to reach out. I'm happy to help whenever the timing's right." if report_url else "A little while back I put together a short audit of your website with the two issues I'd prioritize fixing. If that becomes useful down the line, feel free to reach out. I'm happy to help whenever the timing's right.",
    ]
    if platform_note:
        parts.append(platform_note)
    parts.extend([
        "All the best,",
        "Andrew Ezeani",
        "Teerdox Technologies",
        "https://www.teerdox.com",
    ])
    return "\n\n".join(parts)


def _report_for_outreach(
    draft: Dict[str, Any],
    lead: Optional[Dict[str, Any]] = None,
) -> Optional[Dict[str, Any]]:
    report_id = draft.get("report_id")
    collection = NO_WEBSITE_REPORTS if draft.get("report_type") == "no_website" else AUDIT_REPORTS
    if report_id:
        report = get_document(collection, report_id)
        if report:
            return report

    if collection == AUDIT_REPORTS and lead:
        latest_report_id = str(lead.get("latest_audit_report_id") or "").strip()
        if latest_report_id and latest_report_id != str(report_id or "").strip():
            report = get_document(AUDIT_REPORTS, latest_report_id)
            if report:
                logger.info(
                    "[Outreach Regenerate] Falling back to latest audit report %s for lead %s; draft report %s was missing.",
                    latest_report_id,
                    lead.get("id"),
                    report_id or "none",
                )
                return report
    return None


def _regenerate_campaign_outreach_drafts(campaign_id: str, options: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    settings = get_settings()
    opts = options or {}
    all_emails = bool(opts.get("all_emails"))
    requested_status = str(opts.get("status") or "drafted").strip()
    workflow_type = str(opts.get("workflow_type") or "").strip()
    update_gmail = bool(opts.get("update_gmail_draft"))
    dry_run = bool(opts.get("dry_run", True))
    requested_lead_ids = {
        str(lead_id).strip()
        for lead_id in (opts.get("lead_ids") or [])
        if str(lead_id).strip()
    }

    logger.info(
        "[Outreach Regenerate] Campaign %s started (all_emails=%s status=%s workflow_type=%s "
        "lead_filter=%d update_gmail=%s dry_run=%s).",
        campaign_id,
        all_emails,
        requested_status,
        workflow_type or "any",
        len(requested_lead_ids),
        update_gmail,
        dry_run,
    )

    filters: List[tuple] = [("campaign_id", "==", campaign_id)]
    if not all_emails:
        filters.append(("status", "==", requested_status))
    if workflow_type:
        filters.append(("workflow_type", "==", workflow_type))

    drafts = _query_all_collection(EMAIL_DRAFTS, filters=filters)
    logger.info("[Outreach Regenerate] Campaign %s found %d candidate outreach records.", campaign_id, len(drafts))

    result: Dict[str, Any] = {
        "status": "completed",
        "campaign_id": campaign_id,
        "all_emails": all_emails,
        "status_filter": None if all_emails else requested_status,
        "workflow_type": workflow_type or None,
        "dry_run": dry_run,
        "update_gmail_draft": update_gmail,
        "checked": len(drafts),
        "updated": 0,
        "would_update": 0,
        "gmail_updated": 0,
        "gmail_skipped": 0,
        "notion_updated": 0,
        "skipped": 0,
        "failed": 0,
        "items": [],
    }

    for index, draft in enumerate(drafts, start=1):
        outreach_id = draft["id"]
        lead_id = str(draft.get("lead_id") or "").strip()
        logger.info(
            "[Outreach Regenerate] Campaign %s processing outreach %s (%d/%d, lead=%s, status=%s).",
            campaign_id,
            outreach_id,
            index,
            len(drafts),
            lead_id or "missing",
            draft.get("status") or "",
        )
        if requested_lead_ids and lead_id not in requested_lead_ids:
            result["skipped"] += 1
            result["items"].append({"outreach_id": outreach_id, "lead_id": lead_id, "skipped": True, "reason": "lead_not_selected"})
            continue

        lead = get_document(LEADS, lead_id) if lead_id else None
        if not lead:
            logger.warning("[Outreach Regenerate] Outreach %s skipped: lead %s not found.", outreach_id, lead_id or "missing")
            result["skipped"] += 1
            result["items"].append({"outreach_id": outreach_id, "lead_id": lead_id, "skipped": True, "reason": "lead_not_found"})
            continue
        if lead.get("campaign_id") != campaign_id:
            logger.warning(
                "[Outreach Regenerate] Outreach %s skipped: lead %s belongs to campaign %s, not %s.",
                outreach_id,
                lead_id,
                lead.get("campaign_id"),
                campaign_id,
            )
            result["skipped"] += 1
            result["items"].append({"outreach_id": outreach_id, "lead_id": lead_id, "skipped": True, "reason": "lead_campaign_mismatch"})
            continue

        try:
            email_content = _regenerated_outreach_email_content(draft, lead, settings)
            resolved_report = _report_for_outreach(draft, lead)
            if dry_run:
                result["would_update"] += 1
                result["items"].append({
                    "outreach_id": outreach_id,
                    "lead_id": lead_id,
                    "would_update": True,
                    "status": draft.get("status"),
                    "workflow_type": draft.get("workflow_type"),
                    "subject": email_content["subject"],
                    "email_template_variant": email_content.get("email_template_variant"),
                    "gmail_action": _gmail_regeneration_action(draft, update_gmail),
                })
                continue

            update_payload = {
                "subject": email_content["subject"],
                "body": email_content["body"],
                "template_regenerated_at": datetime.now(timezone.utc).isoformat(),
            }
            notes_status = "sent" if str(draft.get("status") or "").strip().lower() == "sent" else "drafted"
            update_payload["notes"] = append_message_history(
                draft.get("notes"),
                stage=draft.get("stage") or "initial",
                status=notes_status,
                subject=email_content["subject"],
                body=email_content["body"],
                at=update_payload["template_regenerated_at"],
            )
            if email_content.get("email_template_variant"):
                update_payload["email_template_variant"] = email_content["email_template_variant"]
            if resolved_report and resolved_report.get("id") and resolved_report.get("id") != draft.get("report_id"):
                update_payload["report_id"] = resolved_report["id"]
            update_document(EMAIL_DRAFTS, outreach_id, update_payload)
            result["updated"] += 1
            updated_draft = get_document(EMAIL_DRAFTS, outreach_id) or {**draft, **update_payload}
            logger.info("[Outreach Regenerate] Outreach %s Firestore subject/body updated.", outreach_id)

            gmail_action = _gmail_regeneration_action(updated_draft, update_gmail)
            if gmail_action == "update":
                to_email = _primary_email_for_lead(lead)
                if not to_email:
                    gmail_action = "skipped_missing_email"
                    result["gmail_skipped"] += 1
                    logger.warning("[Outreach Regenerate] Outreach %s Gmail update skipped: missing lead email.", outreach_id)
                else:
                    from app.services.gmail_service import update_gmail_draft

                    gmail_body = _append_draft_reference(email_content["body"], outreach_id)
                    if update_gmail_draft(
                        str(updated_draft.get("gmail_draft_id") or ""),
                        to_email,
                        email_content["subject"],
                        gmail_body,
                    ):
                        result["gmail_updated"] += 1
                        gmail_action = "updated"
                        logger.info("[Outreach Regenerate] Outreach %s Gmail draft updated.", outreach_id)
                    else:
                        result["failed"] += 1
                        gmail_action = "failed"
                        logger.error("[Outreach Regenerate] Outreach %s Gmail draft update failed.", outreach_id)
            else:
                result["gmail_skipped"] += 1
                logger.info("[Outreach Regenerate] Outreach %s Gmail update skipped (%s).", outreach_id, gmail_action)

            notion_page_id = get_notion_sync().sync_outreach(
                outreach_id,
                updated_draft,
                lead_notion_page_id=lead.get("notion_page_id"),
                report_notion_page_id=(_report_for_outreach(updated_draft, lead) or {}).get("notion_page_id"),
            )
            if notion_page_id:
                update_document(EMAIL_DRAFTS, outreach_id, {"notion_page_id": notion_page_id})
                result["notion_updated"] += 1
                logger.info("[Outreach Regenerate] Outreach %s synced to Notion page %s.", outreach_id, notion_page_id)

            result["items"].append({
                "outreach_id": outreach_id,
                "lead_id": lead_id,
                "updated": True,
                "status": updated_draft.get("status"),
                "workflow_type": updated_draft.get("workflow_type"),
                "subject": email_content["subject"],
                "email_template_variant": email_content.get("email_template_variant"),
                "gmail_action": gmail_action,
            })
        except Exception as exc:
            result["failed"] += 1
            result["items"].append({"outreach_id": outreach_id, "lead_id": lead_id, "failed": True, "reason": str(exc)})
            logger.error("[Outreach Regenerate] Outreach %s failed: %s", outreach_id, exc, exc_info=True)

    logger.info(
        "[Outreach Regenerate] Campaign %s complete: updated=%d would_update=%d skipped=%d failed=%d gmail_updated=%d.",
        campaign_id,
        result["updated"],
        result["would_update"],
        result["skipped"],
        result["failed"],
        result["gmail_updated"],
    )
    return result


def _regenerated_outreach_email_content(draft: Dict[str, Any], lead: Dict[str, Any], settings: Any) -> Dict[str, str]:
    report = _report_for_outreach(draft, lead)
    if draft.get("parent_outreach_id") or _is_follow_up_outreach(draft):
        parent = draft
        if draft.get("parent_outreach_id"):
            parent = get_document(EMAIL_DRAFTS, str(draft.get("parent_outreach_id") or ""))
            if not parent:
                raise ValueError("parent_outreach_not_found")
        follow_up_count = int(draft.get("follow_up_count") or 1)
        subject = _follow_up_subject(parent, lead, follow_up_count)
        body = _follow_up_body(parent, lead, report, follow_up_count)
        return {"subject": subject, "body": body}

    workflow_type = draft.get("workflow_type") or (
        "no_website" if draft.get("report_type") == "no_website" else "has_website"
    )
    business_name = lead.get("business_name") or lead.get("name") or "there"
    if workflow_type == "no_website":
        if not report:
            raise ValueError("no_website_report_not_found")
        generated_website_url = draft.get("generated_website_url") or lead.get("generated_website_url")
        if not generated_website_url:
            raise ValueError("generated_website_url_missing")
        campaign = get_document(CAMPAIGNS, str(draft.get("campaign_id") or lead.get("campaign_id") or "")) or {}
        from app.services.no_website_appraisal import generate_no_website_email_template

        email_content = generate_no_website_email_template(
            business_name=business_name,
            location=str(lead.get("location") or campaign.get("location") or ""),
            niche=str(campaign.get("niche") or lead.get("niche") or ""),
            no_website_data=report,
            generated_website_url=str(generated_website_url),
        )
        return _maybe_rewrite_outreach_email(
            settings=settings,
            business_name=business_name,
            email_content=email_content,
            factual_guardrails=(
                "The business has no website in the lead record. "
                f"The generated website URL is {generated_website_url}. "
                f"Measured findings: {(report or {}).get('findings', [])[:3]}"
            ),
        )

    if not report:
        raise ValueError("audit_report_not_found")
    slug = str(report.get("slug") or "").strip()
    if not slug:
        raise ValueError("audit_report_slug_missing")
    from app.services.website_appraisal import generate_audit_email_template

    report_base_url = settings.base_url
    email_content = generate_audit_email_template(
        business_name=business_name,
        audit_data=report,
        slug=slug,
        base_url=report_base_url,
    )
    email_template_variant = email_content.get("email_template_variant")
    email_content = _maybe_rewrite_outreach_email(
        settings=settings,
        business_name=business_name,
        email_content=email_content,
        factual_guardrails=(
            "Use only the audit report URL and measured website findings. "
            f"Measured findings: {(report or {}).get('findings', [])[:3]}"
        ),
    )
    if email_template_variant:
        email_content["email_template_variant"] = email_template_variant
    return email_content


def _gmail_regeneration_action(draft: Dict[str, Any], update_gmail: bool) -> str:
    if not update_gmail:
        return "skipped_not_requested"
    if str(draft.get("status") or "").strip() == "sent":
        return "skipped_sent_status"
    if not str(draft.get("gmail_draft_id") or "").strip():
        return "skipped_missing_gmail_draft_id"
    return "update"


def _primary_email_for_lead(lead: Dict[str, Any]) -> Optional[str]:
    emails = lead.get("emails") or []
    if isinstance(emails, list) and emails:
        return str(emails[0] or "").strip() or None
    if isinstance(emails, str) and emails.strip():
        return emails.replace(",", "\n").splitlines()[0].strip() or None
    email = str(lead.get("email") or "").strip()
    return email or None


def _generate_due_follow_up_drafts(
    campaign_id: Optional[str] = None,
    lead_ids: Optional[List[str]] = None,
    limit: int = 25,
    batch_size: int = 10,
) -> Dict[str, Any]:
    settings = get_settings()
    candidates = _due_follow_up_candidates(campaign_id, lead_ids, limit)
    result: Dict[str, Any] = {
        "status": "completed",
        "campaign_id": campaign_id,
        "checked": len(candidates),
        "generated": 0,
        "skipped": 0,
        "failed": 0,
        "batch_size": max(1, int(batch_size or 1)),
        "batches": 0,
        "items": [],
    }
    batches = _chunked(candidates, batch_size)
    result["batches"] = len(batches)
    for batch_index, batch in enumerate(batches, start=1):
        logger.info(
            "[Follow Ups] Processing due follow-up batch %d/%d (%d outreach records).",
            batch_index,
            len(batches),
            len(batch),
        )
        for original in batch:
            outreach_id = original["id"]
            lead_id = original.get("lead_id")
            lead = get_document(LEADS, lead_id or "") if lead_id else None
            if not lead:
                result["skipped"] += 1
                result["items"].append({"outreach_id": outreach_id, "skipped": True, "reason": "lead_not_found"})
                continue
            emails = lead.get("emails") or []
            if not emails:
                result["skipped"] += 1
                result["items"].append({"outreach_id": outreach_id, "lead_id": lead_id, "skipped": True, "reason": "missing_email"})
                continue
            next_count = int(original.get("follow_up_count") or 0) + 1
            stage = _follow_up_stage(next_count)
            report = _report_for_outreach(original)
            subject = _follow_up_subject(original, lead, next_count)
            body = _follow_up_body(original, lead, report, next_count)
            try:
                gmail_draft_id = _create_gmail_draft_with_retries(
                    lead_id=lead_id or "",
                    draft_doc_id=outreach_id,
                    to_email=str(emails[0]),
                    subject=subject,
                    body=body,
                )
                now = datetime.now(timezone.utc)
                notes = append_message_history(
                    original.get("notes"),
                    stage=original.get("stage") or "initial",
                    status="sent",
                    subject=original.get("subject"),
                    body=original.get("body"),
                    at=original.get("sent_at") or original.get("updated_at") or now.isoformat(),
                )
                notes = append_message_history(
                    notes,
                    stage=stage,
                    status="drafted",
                    subject=subject,
                    body=body,
                    at=now.isoformat(),
                )
                update_payload = {
                    "gmail_draft_id": gmail_draft_id,
                    "subject": subject,
                    "body": body,
                    "status": "drafted",
                    "stage": stage,
                    "reply_status": "no_reply",
                    "follow_up_count": next_count,
                    "follow_up_interval_days": _next_follow_up_interval_days(settings, next_count),
                    "last_follow_up_at": now.isoformat(),
                    "follow_up_due_at": None,
                    "notes": notes,
                }
                update_document(EMAIL_DRAFTS, outreach_id, update_payload)
                updated_original = get_document(EMAIL_DRAFTS, outreach_id) or {**original, **update_payload}
                notion_page_id = get_notion_sync().sync_outreach(
                    outreach_id,
                    updated_original,
                    lead_notion_page_id=lead.get("notion_page_id"),
                    report_notion_page_id=(report or {}).get("notion_page_id"),
                )
                result["generated"] += 1
                result["items"].append({
                    "outreach_id": outreach_id,
                    "lead_id": lead_id,
                    "stage": stage,
                    "skipped": False,
                    "reason": "follow_up_draft_updated",
                })
            except Exception as exc:
                result["failed"] += 1
                result["items"].append({
                    "outreach_id": outreach_id,
                    "lead_id": lead_id,
                    "stage": stage,
                    "skipped": False,
                    "reason": "follow_up_failed",
                    "error": str(exc),
                })
                logger.error("[Follow Ups] Outreach %s follow-up draft failed: %s", outreach_id, exc, exc_info=True)
    return result


