@celery_app.task(
    name="tasks.export_campaigns_zip",
    bind=True,
    max_retries=0,
    soft_time_limit=3600,
    time_limit=3900,
)
def export_campaigns_zip(
    self,
    export_id: str,
    campaign_ids: Optional[List[str]] = None,
) -> Dict[str, Any]:
    logger.info("[Export %s] Building campaign export ZIP.", export_id)
    try:
        from app.routes.export import save_campaigns_export, _write_export_status
        filename = save_campaigns_export(export_id, campaign_ids)
        logger.info("[Export %s] Export complete: %s", export_id, filename)
        return {"status": "completed", "export_id": export_id, "filename": filename}
    except Exception as exc:
        logger.error("[Export %s] Export failed: %s", export_id, exc, exc_info=True)
        try:
            from app.routes.export import _write_export_status
            _write_export_status(export_id, {"status": "failed", "error": str(exc)})
        except Exception:
            logger.exception("[Export %s] Could not write failed export status.", export_id)
        return {"status": "failed", "export_id": export_id, "error": str(exc)}


def _sync_campaign_notion_task(
    self,
    campaign_id: str,
    force: bool = False,
    pull_from_notion: bool = True,
) -> Dict[str, Any]:
    logger.info(
        "[Notion Sync] Starting backfill for campaign %s (force=%s, pull_from_notion=%s).",
        campaign_id,
        force,
        pull_from_notion,
    )
    campaign = get_document(CAMPAIGNS, campaign_id)
    if not campaign:
        return {"status": "failed", "reason": "campaign_not_found", "campaign_id": campaign_id}

    update_document(
        CAMPAIGNS,
        campaign_id,
        {
            "progress": {
                "stage": "syncing_notion",
                "message": "Syncing campaign records to Notion.",
            }
        },
    )
    try:
        from app.routes.scrape import _sync_campaign_to_notion
        result = _sync_campaign_to_notion(
            campaign_id,
            campaign,
            force=force,
            pull_from_notion=pull_from_notion,
        ).model_dump()
        update_document(
            CAMPAIGNS,
            campaign_id,
            {
                "progress": {
                    "stage": "notion_sync_complete",
                    "message": "Notion sync completed.",
                }
            },
        )
        logger.info("[Notion Sync] Completed for campaign %s: %s", campaign_id, result)
        return {"status": "completed", **result}
    except Exception as exc:
        logger.error("[Notion Sync] Failed for campaign %s: %s", campaign_id, exc, exc_info=True)
        update_document(
            CAMPAIGNS,
            campaign_id,
            {
                "progress": {
                    "stage": "notion_sync_failed",
                    "message": f"Notion sync failed: {exc}",
                }
            },
        )
        return {"status": "failed", "campaign_id": campaign_id, "error": str(exc)}


@celery_app.task(
    name="tasks.sync_campaign_notion",
    bind=True,
    max_retries=0,
    soft_time_limit=3600,
    time_limit=3900,
)
def sync_campaign_notion(
    self,
    campaign_id: str,
    force: bool = False,
    pull_from_notion: bool = True,
) -> Dict[str, Any]:
    return _sync_campaign_notion_task(self, campaign_id, force, pull_from_notion)


@celery_app.task(
    name="tasks.bulk_delete_campaigns",
    bind=True,
    max_retries=0,
    soft_time_limit=3600,
    time_limit=3900,
)
def bulk_delete_campaigns(self, campaign_ids: Optional[List[str]] = None) -> Dict[str, Any]:
    from app.routes.scrape import (
        _all_campaign_ids,
        _bulk_campaign_action,
        _campaigns_blocking_delete,
        _delete_campaign_doc,
    )
    delete_all = campaign_ids is None
    ids = campaign_ids or _all_campaign_ids()
    if delete_all:
        blocked = _campaigns_blocking_delete(ids)
        if blocked:
            logger.warning(
                "[Cleanup] Bulk delete all blocked by running/analyzing campaigns: %s",
                blocked,
            )
            return {
                "status": "blocked",
                "action": "delete",
                "processed": 0,
                "skipped": len(ids),
                "failed": 0,
                "campaign_ids": [],
                "skipped_campaign_ids": ids,
                "failed_campaign_ids": [],
                "blocking_campaign_ids": blocked,
                "message": "Delete-all was not run because one or more campaigns are running or analyzing.",
            }
    result = _bulk_campaign_action("delete", ids, _delete_campaign_doc).model_dump()
    logger.info("[Cleanup] Bulk delete completed: %s", result)
    return {"status": "completed", **result}


@celery_app.task(
    name="tasks.reconcile_deleting_campaigns",
    bind=True,
    max_retries=0,
    soft_time_limit=120,
)
def reconcile_deleting_campaigns(self) -> Dict[str, Any]:
    """Re-enqueue tombstoned campaigns whose purge never completed.

    Covers the gaps the delete API cannot: crash or broker failure between
    the tombstone and .delay(), lost or expired task records, and purges that
    failed partway (a failed campaign keeps its tombstone because the
    campaign doc is deleted last). bulk_delete_campaigns is idempotent, so
    re-running over a purge that is still in flight is harmless. Scheduled
    by celery beat (see app/workers/celery_app.py beat_schedule).
    """
    from app.routes.scrape import DELETING_REQUEUE_AFTER, _stale_deleting_ids
    from app.schemas import CampaignStatus

    docs = query_collection(
        CAMPAIGNS,
        filters=[("status", "==", CampaignStatus.deleting.value)],
        limit=500,
    )
    now = datetime.now(timezone.utc)
    stale = _stale_deleting_ids(docs, now)
    payload: Dict[str, Any] = {
        "status": "completed",
        "action": "reconcile_deleting",
        "requeued": len(stale),
        "campaign_ids": stale,
    }
    if not stale:
        return payload

    requeue_at = now + DELETING_REQUEUE_AFTER
    for campaign_id in stale:
        update_document(CAMPAIGNS, campaign_id, {"requeue_at": requeue_at})
    bulk_delete_campaigns.delay(stale)
    logger.info("[Cleanup] Re-enqueued %d tombstoned campaign(s): %s", len(stale), stale)
    return payload



